  ('use-item-shiny-stone', 'use-item', null, 'shiny-stone', null, null, null, null, null, null, null, null, null, null, null, null, null, null, false, false, null, null, null, null, null, null, null, false),
  ('use-item-sun-stone', 'use-item', null, 'sun-stone', null, null, null, null, null, null, null, null, null, null, null, null, null, null, false, false, null, null, null, null, null, null, null, false),
