  ('use-item-tart-apple', 'use-item', null, 'tart-apple', null, null, null, null, null, null, null, null, null, null, null, null, null, null, false, false, null, null, null, null, null, null, null, false),
  ('use-item-thunder-stone', 'use-item', null, 'thunder-stone', null, null, null, null, null, null, null, null, null, null, null, null, null, null, false, false, null, null, null, null, null, null, null, false),
