insert into public.pokedex_entries (dex, number, species_id, is_default, ko_description, en_description) values
  ('national', 128, 10419, false, '가라르에 서식하는 켄타로스는 기질이 거칠어서 사람이 등에 올라타는 것을 허용하지 않는다.', 'The Tauros of the Galar region are volatile in nature, and they won’t allow people to ride on their backs.'),
  ('national', 128, 10420, false, '가라르에 서식하는 켄타로스는 기질이 거칠어서 사람이 등에 올라타는 것을 허용하지 않는다.', 'The Tauros of the Galar region are volatile in nature, and they won’t allow people to ride on their backs.'),
  ('national', 128, 10421, false, '가라르에 서식하는 켄타로스는 기질이 거칠어서 사람이 등에 올라타는 것을 허용하지 않는다.', 'The Tauros of the Galar region are volatile in nature, and they won’t allow people to ride on their backs.'),
  ('national', 194, 10422, false, '지상에서 걸을 때는 피부가 건조해지지 않도록 독성분의 점막으로 몸을 감싸고 있다.', 'When walking on land, it covers its body with a poisonous film that keeps its skin from dehydrating.'),
  ('national', 901, 10441, false, null, 'I believe it was Hisui''s swampy terrain that gave Ursaluna its burly physique and newfound capacity to manipulate peat at will.'),
  ('national', 906, 906, true, null, 'The sweet scent its body gives off mesmerizes those around it. The scent grows stronger when this Pokémon is in the sun.'),
  ('national', 907, 907, true, null, 'The hardness of Floragato’s fur depends on the Pokémon’s mood. When Floragato is prepared to battle, its fur becomes pointed and needle sharp.'),
  ('national', 908, 908, true, null, 'With skillful misdirection, it rigs foes with pollen-packed flower bombs. Meowscarada sets off the bombs before its foes realize what’s going on.'),
  ('national', 909, 909, true, null, 'Its flame sac is small, so energy is always leaking out. This energy is released from the dent atop Fuecoco’s head and flickers to and fro.'),
  ('national', 910, 910, true, null, 'The valve in Crocalor’s flame sac is closely connected to its vocal cords. This Pokémon utters a guttural cry as it spews flames every which way.'),
  ('national', 911, 911, true, null, 'Skeledirge’s gentle singing soothes the souls of all that hear it. It burns its enemies to a crisp with flames of over 5,400 degrees Fahrenheit.'),
  ('national', 912, 912, true, null, 'Its strong legs let it easily swim around in even fast-flowing rivers. It likes to keep things tidy and is prone to overthinking things.'),
  ('national', 913, 913, true, null, 'The hardworking Quaxwell observes people and Pokémon from various regions and incorporates their movements into its own dance routines.'),
  ('national', 914, 914, true, null, 'Dancing in ways that evoke far-away places, this Pokémon mesmerizes all that see it. Flourishes of its decorative water feathers slice into its foes.'),
  ('national', 915, 915, true, null, 'This Pokémon spurns all but the finest of foods. Its body gives off an herblike scent that bug Pokémon detest.'),
  ('national', 916, 916, true, null, 'It entrances female Pokémon with the sweet, alluring scent that wafts from all over its body.'),
  ('national', 916, 10423, false, null, 'It entrances female Pokémon with the sweet, alluring scent that wafts from all over its body.'),
  ('national', 917, 917, true, null, 'The thread it secretes from its rear is as strong as wire. The secret behind the thread’s strength is the topic of ongoing research.'),
  ('national', 918, 918, true, null, 'Spidops covers its territory in tough, sticky threads to set up traps for intruders.'),
  ('national', 919, 919, true, null, 'It’s highly skilled at a fighting style in which it uses its jumping capabilities to dodge incoming attacks while also dealing damage to opponents.'),
  ('national', 920, 920, true, null, 'It uses its normally folded third set of legs when in Showdown Mode. This places a huge burden on its body, so it can’t stay in this mode for long.'),
  ('national', 921, 921, true, null, 'The pads of its paws are electricity-discharging organs. Pawmi fires electricity from its forepaws while standing unsteadily on its hind legs.'),
  ('national', 922, 922, true, null, 'Pawmo uses a unique fighting technique in which it uses its forepaws to strike foes and zap them with electricity from its paw pads simultaneously.'),
  ('national', 923, 923, true, null, 'Pawmot’s fluffy fur acts as a battery. It can store the same amount of electricity as an electric car.'),
  ('national', 924, 924, true, null, 'The pair sticks together no matter what. They split any food they find exactly in half and then eat it together.'),
  ('national', 925, 925, true, null, 'The larger pair protects the little ones during battles. When facing strong opponents, the whole group will join the fight.'),
  ('national', 925, 10426, false, null, 'The larger pair protects the little ones during battles. When facing strong opponents, the whole group will join the fight.'),
  ('national', 926, 926, true, null, 'The yeast in Fidough’s breath is useful for cooking, so this Pokémon has been protected by people since long ago.'),
  ('national', 927, 927, true, null, 'The surface of this Pokémon’s skin hardens when exposed to intense heat, and its body has an appetizing aroma.'),
  ('national', 928, 928, true, null, 'This Pokémon converts nutrients into oil, which it stores in the fruit on its head. It can easily go a whole week without eating or drinking.'),
  ('national', 929, 929, true, null, 'It basks in the sun to its heart’s content until the fruits on its head ripen. After that, Dolliv departs from human settlements and goes on a journey.'),
  ('national', 930, 930, true, null, 'This Pokémon drives back enemies by launching its rich, aromatic oil at them with enough force to smash a boulder.'),
  ('national', 931, 931, true, null, 'Green-feathered flocks hold the most sway. When they’re out searching for food in the mornings and evenings, it gets very noisy.'),
  ('national', 931, 10429, false, null, 'Green-feathered flocks hold the most sway. When they’re out searching for food in the mornings and evenings, it gets very noisy.'),
  ('national', 931, 10430, false, null, 'Green-feathered flocks hold the most sway. When they’re out searching for food in the mornings and evenings, it gets very noisy.'),
  ('national', 931, 10431, false, null, 'Green-feathered flocks hold the most sway. When they’re out searching for food in the mornings and evenings, it gets very noisy.'),
  ('national', 932, 932, true, null, 'The ground scrapes its body as it travels, causing it to leave salt behind. Salt is constantly being created and replenished inside Nacli’s body.'),
  ('national', 933, 933, true, null, 'It compresses rock salt inside its body and shoots out hardened salt pellets with enough force to perforate an iron sheet.'),
  ('national', 934, 934, true, null, 'Many Pokémon gather around Garganacl, hoping to lick at its mineral-rich salt.'),
  ('national', 935, 935, true, null, 'Its firepower increases when it fights, reaching over 1,800 degrees Fahrenheit. It likes berries that are rich in fat.'),
  ('national', 936, 936, true, null, 'This Pokémon clads itself in armor that has been fortified by psychic and fire energy, and it shoots blazing fireballs.'),
  ('national', 937, 937, true, null, 'An old set of armor steeped in grudges caused this Pokémon’s evolution. Ceruledge cuts its enemies to pieces without mercy.'),
  ('national', 938, 938, true, null, 'It floats using the electricity stored in its body. When thunderclouds are around, Tadbulb will float higher off the ground.'),
  ('national', 939, 939, true, null, 'What appear to be eyeballs are actually organs for discharging the electricity generated by Bellibolt’s belly-button dynamo.'),
  ('national', 940, 940, true, null, 'These Pokémon make their nests on coastal cliffs. The nests have a strange, crackling texture, and they’re a popular delicacy.'),
  ('national', 941, 941, true, null, 'It uses its throat sac to store electricity generated by its wings. There’s hardly any oil in its feathers, so it is a poor swimmer.'),
  ('national', 942, 942, true, null, 'Its well-developed jaw and fangs are strong enough to crunch through boulders, and its thick fat makes for an excellent defense.'),
  ('national', 943, 943, true, null, 'Mabosstiff loves playing with children. Though usually gentle, it takes on an intimidating look when protecting its family.'),
  ('national', 944, 944, true, null, 'To keep enemies away from its territory, it paints markings around its nest using a poisonous liquid that has an acrid odor.'),
  ('national', 945, 945, true, null, 'Each Grafaiai paints its own individual pattern, and it will paint that same pattern over and over again throughout its life.'),
  ('national', 946, 946, true, null, 'Not even Bramblin knows where it is headed as it tumbles across the wilderness, blown by the wind. It loathes getting wet.'),
  ('national', 947, 947, true, null, 'Brambleghast wanders around arid regions. On rare occasions, mass outbreaks of these Pokémon will bury an entire town.'),
  ('national', 948, 948, true, null, 'Though it looks like Tentacool, Toedscool is a completely different species. Its legs may be thin, but it can run at a speed of 30 mph.'),
  ('national', 949, 949, true, null, 'It coils its 10 tentacles around prey and sucks out their nutrients, causing the prey pain. The folds along the rim of its head are a popular delicacy.'),
  ('national', 950, 950, true, null, 'This Pokémon lives on sheer cliffs. It sidesteps opponents’ attacks, then lunges for their weak spots with its claws.'),
  ('national', 951, 951, true, null, 'Traditional Paldean dishes can be extremely spicy because they include the shed front teeth of Capsakid among their ingredients.'),
  ('national', 952, 952, true, null, 'The green head has turned vicious due to the spicy chemicals stimulating its brain. Once it goes on a rampage, there is no stopping it.'),
  ('national', 953, 953, true, null, 'It rolls its mud ball around while the energy it needs for evolution matures. Eventually the time comes for it to evolve.'),
  ('national', 954, 954, true, null, 'An infant sleeps inside the ball. Rabsca rolls the ball soothingly with its legs to ensure the infant sleeps comfortably.'),
  ('national', 955, 955, true, null, 'It spends its time running around wastelands. If anyone steals its beloved berries, it will chase them down and exact its revenge.'),
  ('national', 956, 956, true, null, 'It emits psychic power from the gaps between its multicolored frills and sprints at speeds greater than 120 mph.'),
  ('national', 957, 957, true, null, 'This Pokémon pounds iron scraps together to make a hammer. It will remake the hammer again and again until it’s satisfied with the result.'),
  ('national', 958, 958, true, null, 'These Pokémon make their homes in piles of scrap metal. They test the strength of each other’s hammers by smashing them together.'),
  ('national', 959, 959, true, null, 'The hammer tops 220 pounds, yet it gets swung around easily by Tinkaton as it steals whatever it pleases and carries its plunder back home.'),
  ('national', 960, 960, true, null, 'Though it looks like Diglett, Wiglett is an entirely different species. The resemblance seems to be a coincidental result of environmental adaptation.'),
  ('national', 961, 961, true, null, 'A variety of fish Pokémon, Wugtrio was once considered to be a regional form of Dugtrio.'),
  ('national', 962, 962, true, null, 'Bombirdier uses the apron on its chest to bundle up food, which it carries back to its nest. It enjoys dropping things that make loud noises.'),
  ('national', 963, 963, true, null, 'Its water ring is made from seawater mixed with a sticky fluid that Finizen secretes from its blowhole.'),
  ('national', 964, 964, true, null, 'Its physical capabilities are no different than a Finizen’s, but when its allies are in danger, it transforms and powers itself up.'),
  ('national', 964, 10425, false, null, 'Its physical capabilities are no different than a Finizen’s, but when its allies are in danger, it transforms and powers itself up.'),
  ('national', 965, 965, true, null, 'The steel section is Varoom’s actual body. This Pokémon clings to rocks and converts the minerals within into energy to fuel its activities.'),
  ('national', 966, 966, true, null, 'Revavroom viciously threatens others with the sound of its exhaust. It sticks its tongue out from its cylindrical mouth and sprays toxic fluids.'),
  ('national', 967, 967, true, null, 'It can sprint at over 70 mph while carrying a human. The rider’s body heat warms Cyclizar’s back and lifts the Pokémon’s spirit.'),
  ('national', 968, 968, true, null, 'This Pokémon lives in arid deserts. It maintains its metal body by consuming iron from the soil.'),
  ('national', 969, 969, true, null, 'Glimmet’s toxic mineral crystals look just like flower petals. This Pokémon scatters poisonous powder like pollen to protect itself.'),
  ('national', 970, 970, true, null, 'Glimmora’s petals are made of crystallized poison energy. It has recently become evident that these petals resemble Tera Jewels.'),
  ('national', 971, 971, true, null, 'This friendly Pokémon doesn’t like being alone. Pay it even the slightest bit of attention, and it will follow you forever.'),
  ('national', 972, 972, true, null, 'A lovingly mourned Pokémon was reborn as Houndstone. It doesn’t like anyone touching the protuberance atop its head.'),
  ('national', 973, 973, true, null, 'Thanks to a behavior of theirs known as “synchronizing,” an entire flock of these Pokémon can attack simultaneously in perfect harmony.'),
  ('national', 974, 974, true, null, 'It lives in frigid regions in pods of five or so individuals. It loves the minerals found in snow and ice.'),
  ('national', 975, 975, true, null, 'Ice energy builds up in the horn on its upper jaw, causing the horn to reach cryogenic temperatures that freeze its surroundings.'),
  ('national', 976, 976, true, null, 'Veluza has excellent regenerative capabilities. It sheds spare flesh from its body to boost its agility, then charges at its prey.'),
  ('national', 977, 977, true, null, 'It treats Tatsugiri like its boss and follows it loyally. Though powerful, Dondozo is apparently not very smart.'),
  ('national', 978, 978, true, null, 'Tatsugiri is an extremely cunning Pokémon. It feigns weakness to lure in prey, then orders its partner to attack.'),
  ('national', 978, 10427, false, null, 'Tatsugiri is an extremely cunning Pokémon. It feigns weakness to lure in prey, then orders its partner to attack.'),
  ('national', 978, 10428, false, null, 'Tatsugiri is an extremely cunning Pokémon. It feigns weakness to lure in prey, then orders its partner to attack.'),
  ('national', 979, 979, true, null, 'It imbues its fists with the power of the rage that it kept hidden in its heart. Opponents struck by these imbued fists will be shattered to their core.'),
  ('national', 980, 980, true, null, 'It lives at the bottom of ponds and swamps. It will carry Wooper on its back and ferry them across water from one shore to the other.'),
  ('national', 981, 981, true, null, 'The hardened head from the tail protects the head of the main body as Farigiraf whips its long neck around to headbutt enemies.'),
  ('national', 982, 982, true, null, 'It drives enemies out of its nest by sucking in enough air to fill its long, narrow lungs, then releasing the air in an intense blast.'),
  ('national', 982, 10424, false, null, 'It drives enemies out of its nest by sucking in enough air to fill its long, narrow lungs, then releasing the air in an intense blast.'),
  ('national', 983, 983, true, null, 'Though it commands a massive army in battle, it’s not skilled at devising complex strategies. It just uses brute strength to keep pushing.'),
  ('national', 984, 984, true, null, 'This creature resembles a mysterious Pokémon that, according to a paranormal magazine, has lived since ancient times.'),
  ('national', 985, 985, true, null, 'It resembles a mysterious Pokémon described in a paranormal magazine as a Jigglypuff from one billion years ago.'),
  ('national', 986, 986, true, null, 'It bears a slight resemblance to a Pokémon described in a dubious magazine as a cross between a dinosaur and a mushroom.'),
  ('national', 987, 987, true, null, 'It has similar features to a ghostly pterosaur that was covered in a paranormal magazine, but the two have little else in common.'),
  ('national', 988, 988, true, null, 'This Pokémon somewhat resembles an ancient form of Volcarona that was introduced in a dubious magazine.'),
  ('national', 989, 989, true, null, 'It slightly resembles a Magneton that lived for 10,000 years and was featured in an article in a paranormal magazine.'),
  ('national', 990, 990, true, null, 'Sightings of this Pokémon have occurred in recent years. It resembles a mysterious object described in an old expedition journal.'),
  ('national', 991, 991, true, null, 'It resembles a mysterious object mentioned in an old book. There are only two reported sightings of this Pokémon.'),
  ('national', 992, 992, true, null, 'This Pokémon shares many similarities with Iron Hands, an object mentioned in a certain expedition journal.'),
  ('national', 993, 993, true, null, 'It’s possible that Iron Jugulis, an object described in an old book, may actually be this Pokémon.'),
  ('national', 994, 994, true, null, 'No records exist of this species being caught. Data is lacking, but the Pokémon’s traits match up with an object described in an old book.'),
  ('national', 995, 995, true, null, 'Some of its notable features match those of an object named within a certain expedition journal as Iron Thorns.'),
  ('national', 996, 996, true, null, 'This Pokémon lives in forests and craggy areas. Using the power of its dorsal fin, it cools the inside of its nest like a refrigerator.'),
  ('national', 997, 997, true, null, 'It attacks with the blade of its frozen dorsal fin by doing a front flip in the air. Arctibax’s strong back and legs allow it to pull off this technique.'),
  ('national', 998, 998, true, null, 'It launches itself into battle by flipping upside down and spewing frigid air from its mouth. It finishes opponents off with its dorsal blade.'),
  ('national', 999, 999, true, null, 'It lives inside an old treasure chest. Sometimes it gets left in shop corners since no one realizes it’s actually a Pokémon.'),
  ('national', 999, 10432, false, null, 'It lives inside an old treasure chest. Sometimes it gets left in shop corners since no one realizes it’s actually a Pokémon.'),
  ('national', 1000, 1000, true, null, 'It has a sturdy body made up of stacked coins. Gholdengo overwhelms its enemies by firing coin after coin at them in quick succession.'),
  ('national', 1001, 1001, true, null, 'It drains the life-force from vegetation, causing nearby forests to instantly wither and fields to turn barren.'),
  ('national', 1002, 1002, true, null, 'The hatred of those who perished by the sword long ago has clad itself in snow and become a Pokémon.'),
  ('national', 1003, 1003, true, null, 'It slowly brings its exceedingly heavy head down upon the ground, splitting the earth open with huge fissures that run over 160 feet deep.'),
  ('national', 1004, 1004, true, null, 'The envy accumulated within curved beads that sparked multiple conflicts has clad itself in fire and become a Pokémon.'),
  ('national', 1005, 1005, true, null, 'According to an article in a dubious magazine, this Pokémon has some connection to a phenomenon that occurs in a certain region.'),
  ('national', 1006, 1006, true, null, 'It’s possible that this is the object listed as Iron Valiant in a certain expedition journal.'),
  ('national', 1007, 1007, true, null, 'This Pokémon resembles Cyclizar, but it is far burlier and more ferocious. Nothing is known about its ecology or other features.'),
  ('national', 1008, 1008, true, null, 'This seems to be the Iron Serpent mentioned in an old book. The Iron Serpent is said to have turned the land to ash with its lightning.'),
  ('national', 1009, 1009, true, null, 'It resembles an illustration published in a paranormal magazine, said to be a depiction of a super-ancient Suicune.'),
  ('national', 1010, 1010, true, null, 'According to the few eyewitness accounts that exist, it used its shining blades to julienne large trees and boulders.'),
  ('national', 1011, 1011, true, null, 'The head sticking out belongs to the fore-wyrm, while the tail belongs to the core-wyrm. The two share one apple and help each other out.'),
  ('national', 1012, 1012, true, null, 'Poltchageist looks like a regional form of Sinistea, but it was recently discovered that the two Pokémon are entirely unrelated.'),
  ('national', 1013, 1013, true, null, 'It prefers cool, dark places, such as the back of a shelf or the space beneath a home''s floorboards. It wanders in search of prey after sunset.'),
  ('national', 1014, 1014, true, null, 'Okidogi is a ruffian with a short temper. It can pulverize anything by swinging around the chain on its neck.'),
  ('national', 1015, 1015, true, null, 'Munkidori keeps itself somewhere safe while it toys with its foes, using psychokinesis to induce intense dizziness.'),
  ('national', 1016, 1016, true, null, 'Fezandipiti beats its glossy wings to scatter pheromones that captivate people and Pokémon.'),
  ('national', 1017, 1017, true, null, 'This mischief-loving Pokémon is full of curiosity. It battles by drawing out the type-based energy contained within its masks.'),
  ('national', 1017, 10442, false, null, 'This mischief-loving Pokémon is full of curiosity. It battles by drawing out the type-based energy contained within its masks.'),
  ('national', 1017, 10443, false, null, 'This mischief-loving Pokémon is full of curiosity. It battles by drawing out the type-based energy contained within its masks.'),
  ('national', 1017, 10444, false, null, 'This mischief-loving Pokémon is full of curiosity. It battles by drawing out the type-based energy contained within its masks.'),
  ('national', 1018, 1018, true, null, 'It digs holes on mountains, searching for food. It’s so durable that being caught in a cave-in won’t faze it.'),
  ('national', 1019, 1019, true, null, 'These capricious syrpents have banded together. On the rare occasion that their moods align, their true power is unleashed.'),
  ('national', 1020, 1020, true, null, 'It resembles an eerie Pokémon once shown in a paranormal magazine. That Pokémon was said to be an Entei regenerated from a fossil.'),
  ('national', 1021, 1021, true, null, 'It bears resemblance to a Pokémon that became a hot topic for a short while after a paranormal magazine touted it as Raikou''s ancestor.'),
  ('national', 1022, 1022, true, null, 'It was named after a mysterious object recorded in an old book. Its body seems to be metallic.'),
  ('national', 1023, 1023, true, null, 'There was supposedly an incident in which it launched shining blades to cut everything around it to pieces. Little else is known about it.'),
  ('national', 1024, 1024, true, null, 'It’s thought that this Pokémon lived in ancient Paldea until it got caught in seismic shifts and went extinct.'),
  ('national', 1024, 10445, false, null, 'It’s thought that this Pokémon lived in ancient Paldea until it got caught in seismic shifts and went extinct.'),
  ('national', 1024, 10446, false, null, 'It’s thought that this Pokémon lived in ancient Paldea until it got caught in seismic shifts and went extinct.'),
  ('national', 1025, 1025, true, null, 'Its peach-shaped shell serves as storage for a potent poison. It makes poisonous mochi and serves them to people and Pokémon.'),
  ('kanto', 128, 10419, false, '넘치는 체력의 난동꾼. 달리기 시작하면 몸통박치기를 할 때까지 끝없이 돌진한다.', 'A rowdy Pokémon with a lot of stamina. Once running, it won’t stop until it hits something.'),
  ('kanto', 128, 10420, false, '넘치는 체력의 난동꾼. 달리기 시작하면 몸통박치기를 할 때까지 끝없이 돌진한다.', 'A rowdy Pokémon with a lot of stamina. Once running, it won’t stop until it hits something.'),
  ('kanto', 128, 10421, false, '넘치는 체력의 난동꾼. 달리기 시작하면 몸통박치기를 할 때까지 끝없이 돌진한다.', 'A rowdy Pokémon with a lot of stamina. Once running, it won’t stop until it hits something.'),
  ('johto', 56, 10422, false, '지상에서 걸을 때는 피부가 건조해지지 않도록 독성분의 점막으로 몸을 감싸고 있다.', 'This Pokémon lives in cold water. It will leave the water to search for food when it gets cold outside.'),
  ('johto', 148, 10419, false, '가라르에 서식하는 켄타로스는 기질이 거칠어서 사람이 등에 올라타는 것을 허용하지 않는다.', 'They fight each other by locking horns. The herd’s protector takes pride in its battle-scarred horns.'),
  ('johto', 148, 10420, false, '가라르에 서식하는 켄타로스는 기질이 거칠어서 사람이 등에 올라타는 것을 허용하지 않는다.', 'They fight each other by locking horns. The herd’s protector takes pride in its battle-scarred horns.'),
  ('johto', 148, 10421, false, '가라르에 서식하는 켄타로스는 기질이 거칠어서 사람이 등에 올라타는 것을 허용하지 않는다.', 'They fight each other by locking horns. The herd’s protector takes pride in its battle-scarred horns.'),
  ('sinnoh', 117, 10422, false, '지상에서 걸을 때는 피부가 건조해지지 않도록 독성분의 점막으로 몸을 감싸고 있다.', 'When walking on land, it covers its body with a poisonous film that keeps its skin from dehydrating.'),
  ('kalos', 275, 10419, false, '3개의 꼬리로 자신을 때려서 투지가 끓어오르면 전속력으로 돌진해온다.', 'After heightening its will to fight by whipping itself with its three tails, it charges at full speed.'),
  ('kalos', 275, 10420, false, '3개의 꼬리로 자신을 때려서 투지가 끓어오르면 전속력으로 돌진해온다.', 'After heightening its will to fight by whipping itself with its three tails, it charges at full speed.'),
  ('kalos', 275, 10421, false, '3개의 꼬리로 자신을 때려서 투지가 끓어오르면 전속력으로 돌진해온다.', 'After heightening its will to fight by whipping itself with its three tails, it charges at full speed.'),
  ('kalos', 320, 10422, false, '차가운 물속에서 생활한다. 근처가 선선해지면 먹이를 찾으러 지상에도 나타난다.', 'This Pokémon lives in cold water. It will leave the water to search for food when it gets cold outside.'),
  ('alola', 170, 10419, false, '집단생활을 한다. 무리 중에서 가장 굵고 길며 상처가 많은 뿔을 가진 것이 보스다.', 'They live in groups. The one with the longest, thickest, and most-scarred horns is the boss of the herd.'),
  ('alola', 170, 10420, false, '집단생활을 한다. 무리 중에서 가장 굵고 길며 상처가 많은 뿔을 가진 것이 보스다.', 'They live in groups. The one with the longest, thickest, and most-scarred horns is the boss of the herd.'),
  ('alola', 170, 10421, false, '집단생활을 한다. 무리 중에서 가장 굵고 길며 상처가 많은 뿔을 가진 것이 보스다.', 'They live in groups. The one with the longest, thickest, and most-scarred horns is the boss of the herd.'),
  ('galar', 100, 10422, false, '차가운 물속에서 생활한다. 근처가 선선해지면 먹이를 찾으러 지상에도 나타난다.', 'This Pokémon lives in cold water. It will leave the water to search for food when it gets cold outside.'),
  ('galar', 461, 10419, false, '꼬리로 자신의 몸을 때리기 시작하면 위험하다. 맹렬한 스피드로 덤벼든다.', 'When Tauros begins whipping itself with its tails, it’s a warning that the Pokémon is about to charge with astounding speed.'),
  ('galar', 461, 10420, false, '꼬리로 자신의 몸을 때리기 시작하면 위험하다. 맹렬한 스피드로 덤벼든다.', 'When Tauros begins whipping itself with its tails, it’s a warning that the Pokémon is about to charge with astounding speed.'),
  ('galar', 461, 10421, false, '꼬리로 자신의 몸을 때리기 시작하면 위험하다. 맹렬한 스피드로 덤벼든다.', 'When Tauros begins whipping itself with its tails, it’s a warning that the Pokémon is about to charge with astounding speed.'),
  ('hisui', 114, 10441, false, null, 'I believe it was Hisui''s swampy terrain that gave Ursaluna its burly physique and newfound capacity to manipulate peat at will.'),
  ('paldea', 1, 906, true, null, 'Its fluffy fur is similar in composition to plants. This Pokémon frequently washes its face to keep it from drying out.'),
  ('paldea', 2, 907, true, null, 'Floragato deftly wields the vine hidden beneath its long fur, slamming the hard flower bud against its opponents.'),
  ('paldea', 3, 908, true, null, 'This Pokémon uses the reflective fur lining its cape to camouflage the stem of its flower, creating the illusion that the flower is floating.'),
  ('paldea', 4, 909, true, null, 'It lies on warm rocks and uses the heat absorbed by its square-shaped scales to create fire energy.'),
  ('paldea', 5, 910, true, null, 'The combination of Crocalor’s fire energy and overflowing vitality has caused an egg-shaped fireball to appear on the Pokémon’s head.'),
  ('paldea', 6, 911, true, null, 'The fiery bird changes shape when Skeledirge sings. Rumor has it that the bird was born when the fireball on Skeledirge’s head gained a soul.'),
  ('paldea', 7, 912, true, null, 'This Pokémon migrated to Paldea from distant lands long ago. The gel secreted by its feathers repels water and grime.'),
  ('paldea', 8, 913, true, null, 'These Pokémon constantly run through shallow waters to train their legs, then compete with each other to see which of them kicks most gracefully.'),
  ('paldea', 9, 914, true, null, 'A single kick from a Quaquaval can send a truck rolling. This Pokémon uses its powerful legs to perform striking dances from far-off lands.'),
  ('paldea', 10, 915, true, null, 'It searches for food all day. It possesses a keen sense of smell but doesn’t use it for anything other than foraging.'),
  ('paldea', 11, 916, true, null, 'Oinkologne is proud of its fine, glossy skin. It emits a concentrated scent from the tip of its tail.'),
  ('paldea', 11, 10423, false, null, 'Oinkologne is proud of its fine, glossy skin. It emits a concentrated scent from the tip of its tail.'),
  ('paldea', 12, 917, true, null, 'The ball of threads wrapped around its body is elastic enough to deflect the scythes of Scyther, this Pokémon’s natural enemy.'),
  ('paldea', 13, 918, true, null, 'It clings to branches and ceilings using its threads and moves without a sound. It takes out its prey before the prey even notices it.'),
  ('paldea', 14, 919, true, null, 'It has its third set of legs folded up. When it’s in a tough spot, this Pokémon jumps over 30 feet using the strength of its legs.'),
  ('paldea', 15, 920, true, null, 'When it decides to fight all out, it stands on its previously folded legs to enter Showdown Mode. It neutralizes its enemies in short order.'),
  ('paldea', 16, 187, true, '바람을 타고 둥둥 떠다니는 포켓몬이다. 강풍의 기척을 느끼면 동료끼리 잎사귀를 휘감아 날아가지 않도록 준비한다.', 'This Pokémon drifts and floats with the wind. If it senses the approach of strong winds, Hoppip links its leaves with other Hoppip to prepare against being blown away.'),
  ('paldea', 17, 188, true, '기온이 18도를 넘으면 꽃이 핀다. 온도에 따라 꽃이 피는 모습이 바뀌어서 온도계 대신 쓰기도 한다.', 'Skiploom’s flower blossoms when the temperature rises above 64 degrees Fahrenheit. How much the flower opens depends on the temperature. For that reason, this Pokémon is sometimes used as a thermometer.'),
  ('paldea', 18, 189, true, '따뜻한 남풍을 타고 바다를 건너 외국까지 날아가는 포켓몬이다. 차가운 공기에 닿으면 땅에 내려온다.', 'Jumpluff rides warm southern winds to cross the sea and fly to foreign lands. The Pokémon descends to the ground when it encounters cold air while it is floating.'),
  ('paldea', 19, 661, true, '흥분하면 체온이 확 오른다. 맨손으로 만지면 화상을 입기도 할 정도다.', 'When this Pokémon gets excited, its body temperature increases sharply. If you touch a Fletchling with bare hands, you might get burned.'),
  ('paldea', 20, 662, true, '영역에 대한 개념이 매우 강하고 호전적이다. 먹이 먹는 장소를 두고 불화살빈끼리 싸운다.', 'Fletchinder are exceedingly territorial and aggressive. These Pokémon fight among themselves over feeding grounds.'),
  ('paldea', 21, 663, true, '시속 500km로 돌격한다. 먹이가 도망칠 틈을 주지 않고 강렬한 발차기로 꼼짝 못 하게 한다.', 'Talonflame dives toward prey at speeds of up to 310 mph and assaults them with powerful kicks, giving the prey no chance to escape.'),
  ('paldea', 22, 921, true, null, 'It has underdeveloped electric sacs on its cheeks. These sacs can produce electricity only if Pawmi rubs them furiously with the pads on its forepaws.'),
  ('paldea', 23, 922, true, null, 'When its group is attacked, Pawmo is the first to leap into battle, defeating enemies with a fighting technique that utilizes electric shocks.'),
  ('paldea', 24, 923, true, null, 'This Pokémon normally is slow to react, but once it enters battle, it will strike down its enemies with lightning-fast movements.'),
  ('paldea', 25, 228, true, '동이 트기 전에 기분 나쁜 울음을 반복하여 자신들 무리의 존재를 어필한다.', 'They make repeated eerie howls before dawn to call attention to their pack.'),
  ('paldea', 26, 229, true, '기분 나쁜 울음소리가 특징이다. 옛날 사람들은 지옥에서 온 사자라고 여겨 두려워했다.', 'Identifiable by its eerie howls, people a long time ago thought it was the grim reaper and feared it.'),
  ('paldea', 26, 10148, false, '기분 나쁜 울음소리가 특징이다. 옛날 사람들은 지옥에서 온 사자라고 여겨 두려워했다.', 'Identifiable by its eerie howls, people a long time ago thought it was the grim reaper and feared it.'),
  ('paldea', 27, 734, true, '무엇이든 먹지만 신선하고 살아 있는 것을 좋아해서 먹이를 찾아 길을 누비고 다닌다.', 'Although it will eat anything, it prefers fresh living things, so it marches down streets in search of prey.'),
  ('paldea', 28, 735, true, '매우 인내심이 강한 성질이지만 좋아하는 꼬렛을 발견하면 이성을 잃고 덤벼든다.', 'Patient by nature, this Pokémon loses control of itself and pounces when it spots its favorite meal—Rattata!'),
  ('paldea', 29, 819, true, '항상 나무열매를 먹고 있어 보기보다 튼튼하다. 나무열매를 노리고 밭에 출몰한다.', 'It eats berries nonstop—a habit that has made it more resilient than it looks. It’ll show up on farms, searching for yet more berries.'),
  ('paldea', 30, 820, true, '아무리 단단한 나무열매 껍질도 이빨로 아작아작 갉아 먹는다. 가라르에서 쉽게 볼 수 있는 포켓몬이다.', 'Common throughout the Galar region, this Pokémon has strong teeth and can chew through the toughest of berry shells.'),
  ('paldea', 31, 191, true, '몸에 모은 영양을 진화할 때까지 간직하기 위해 거의 움직이려 하지 않는다. 아무것도 먹지 않고 아침 이슬만 마시고 있다.', 'Sunkern tries to move as little as it possibly can. It does so because it tries to conserve all the nutrients it has stored in its body for its evolution. It will not eat a thing, subsisting only on morning dew.'),
  ('paldea', 32, 192, true, '태양 에너지에서 영양을 만들어낸다. 기온이 높은 낮에는 활발하게 움직이고 태양이 지면 뚝 하니 움직이지 않게 된다.', 'Sunflora converts solar energy into nutrition. It moves around actively in the daytime when it is warm. It stops moving as soon as the sun goes down for the night.'),
  ('paldea', 33, 401, true, '더듬이가 서로 부딪히면 딩동딩동 실로폰 같은 음색을 연주한다.', 'When the trees take on new hues, more of these Pokémon appear. The tone they create by striking their antennae together resembles that of the marimba, an instrument of foreign lands.'),
  ('paldea', 34, 402, true, '감정을 멜로디로 나타낸다. 멜로디의 법칙성을 학자들이 연구하고 있다.', 'It uses its cutlass-like arms to produce sound, the melody of which varies from individual to individual. It is a worthwhile endeavor to seek out one''s favorite tunes.'),
  ('paldea', 35, 664, true, '몸을 덮은 가루가 체온을 조절하고 있어 어떤 기후나 풍토의 지역에서도 살 수 있다.', 'The powder that covers its body regulates its temperature, so it can live in any region or climate.'),
  ('paldea', 36, 665, true, '단단한 몸은 새포켓몬의 부리로도 상처 하나 입지 않는다. 가루를 뿌려서 방어한다.', 'The beaks of bird Pokémon can’t begin to scratch its stalwart body. To defend itself, it spews powder.'),
  ('paldea', 37, 666, true, '살고 있는 장소의 기후나 풍토에 따라 날개의 모양이 다른 포켓몬이다. 화려한 색의 날개 가루를 뿌린다.', 'The patterns on this Pokémon’s wings depend on the climate and topography of its habitat. It scatters colorful scales.'),
  ('paldea', 37, 10086, false, '살고 있는 장소의 기후나 풍토에 따라 날개의 모양이 다른 포켓몬이다. 화려한 색의 날개 가루를 뿌린다.', 'The patterns on this Pokémon’s wings depend on the climate and topography of its habitat. It scatters colorful scales.'),
